[neo@netkiller test]# tree a a ├── a.py ├── a.sh └── b ├── b.py ├── b.sh ├── c │ └── c.sh └── d └── d.sh
[neo@netkiller test]# find ./a -type f -regex ".*\.sh$" | sed -r -n 's#(.*\.)sh$#mv & \1shell#e' [neo@netkiller test]# tree a a ├── a.py ├── a.shell └── b ├── b.py ├── b.shell ├── c │ └── c.shell └── d └── d.shell
// 注意 sed s->e 使用方式,官方文档是这样解释的. This command allows one to pipe input from a shell command into pattern space. If a substitution was made, the command that is found in pattern space is executed and pattern space is replaced with its output. A trailing newline is suppressed; results are undefined if the command to be executed contains a NUL character. This is a GNU sed extension.

# find -type f -name "*.js" -exec grep -H -A2 openWindow {} \;

./javascript/commonjs.js:function openWindow(url){
./javascript/commonjs.js-	window.open(url + "?rand=" + getRandom(), 'gamebinary');
./javascript/commonjs.js-}

find -type f -regex ".*\.\(css\|js\)" -exec yuicompressor {} -o {} \;
find -type f -name "*.js" -exec yuicompressor --type js {} -o {} \;
find -type f -name "*.css" -exec yuicompressor --type css {} -o {} \;

